"""Rule-based mock interview; feedback is heuristic, not generated by an LLM."""
import re

def make_questions(matched_skills, missing_skills, role="the selected role"):
    skills = list(dict.fromkeys([str(x) for x in matched_skills + missing_skills]))
    questions = [
        {"question": f"Tell me about yourself and why you are interested in {role}.",
         "keywords": ["project", "skill", "experience", "learn"]},
        {"question": "Describe a challenging project, your specific contribution, and its outcome.",
         "keywords": ["problem", "built", "result", "learned"]},
    ]
    for skill in skills[:3]:
        questions.append({
            "question": f"Explain how you would use {skill} in a real project. Give a specific example.",
            "keywords": [skill.lower(), "project", "example", "result"]
        })
    return questions

def evaluate_answer(answer, keywords):
    words = re.findall(r"\b[\w+-]+\b", answer.lower())
    matched = [kw for kw in keywords if kw.lower() in answer.lower()]
    score = min(100, round(25 * min(len(words), 65) / 65
                           + 45 * len(matched) / max(1, len(keywords))
                           + (20 if len(words) >= 45 else 0)
                           + (10 if any(x in answer.lower() for x in ["because", "therefore", "result", "improved", "learned"]) else 0)))
    tips = []
    if len(words) < 45:
        tips.append("Add detail: explain the situation, your action, and the result.")
    if len(matched) < len(keywords):
        tips.append("Address the question directly and include relevant technical examples.")
    if not any(x in answer.lower() for x in ["result", "improved", "achieved", "learned"]):
        tips.append("Describe a measurable result or what you learned.")
    if not tips:
        tips.append("Good structure. Keep your examples accurate and concise.")
    return {"score": score, "tips": tips, "matched_keywords": matched,
            "note": "Heuristic practice feedback, not an assessment of correctness or an LLM evaluation."}
